                R(ref s, "I believe I warned you about this, <E049><E003 6>witness.", "Il me semble vous avoir averti à ce propos, <E049><E003 6>témoin.");
                R(ref s, "I promised to curtail your testimony as soon as it entered\r\nthe realms of supposition or speculation.", "J'ai promis d'interrompre votre déposition dès lors qu'elle\r\nentrerait dans le domaine des suppositions ou des conjectures.");
                R(ref s, "Very well, <E049><E003 8>My Lord.", "Très bien, <E049><E003 8>Votre Honneur.");
