                R(ref s, "I have the right to cross-examine every witness after\r\ntestimony.", "J'ai le droit de contre-interroger chaque témoin après\r\nsa déposition.");
                R(ref s, "And I fully intend <E049><E003 10><E025 1><E164 1 8 1 2 8 0 1 1><E139 1><E025 1><E092 1>to exercise that right!", "Et j'ai bien l'intention <E049><E003 10><E025 1><E164 1 8 1 2 8 0 1 1><E139 1><E025 1><E092 1>d'exercer ce droit !");
                R(ref s, "I'm afraid that even the presiding judge...", "J'ai bien peur que même le juge président...");
                R(ref s, "...has no authority to contravene the letter of the law.", "...n'ait pas l'autorité nécessaire pour enfreindre la lettre de la loi.");
                R(ref s, "As I'm sure <E049><E003 10><E025 1><E332>every member of the judiciary present in the\r\ngallery would agree!", "Comme en conviendront certainement <E049><E003 10><E025 1><E332>tous les membres de la\r\nmagistrature présents dans la tribune !");
