                R(ref s, "But then you couldn't say there wasn't any indication,\r\neither...<E049><E003 6><E025 1><E164 112 7 1 2 5 0 1 1><E139 112>could you?", "Mais alors, vous ne pourriez pas non plus affirmer qu'il n'y avait\r\naucun signe...<E049><E003 6><E025 1><E164 112 7 1 2 5 0 1 1><E139 112>n'est-ce pas ?");
                R(ref s, "No, <E049><E003 8>true, <E049><E003 6>I couldn't.", "Non, <E049><E003 8>c'est vrai, <E049><E003 6>en effet.");
                R(ref s, "I was at Dr Wilson's side as he performed the procedure,<E049><E003 8>\r\nrecording what he did.", "J'étais aux côtés du Dr Wilson lorsqu'il pratiquait l'examen,<E049><E003 8>\r\nconsignant ce qu'il faisait.");
                R(ref s, "But at times of course, <E049><E003 6>he instructed me to fetch\r\nimplements and suchlike.", "Mais par moments bien sûr, <E049><E003 6>il m'ordonnait d'aller chercher\r\ndes instruments ou autres.");
                R(ref s, "Whilst I was away from the operating table, <E049><E003 6>obviously I\r\ncould have missed something.", "Pendant que j'étais éloigné de la table d'opération, <E049><E003 6>j'aurais fort\r\nbien pu manquer quelque chose.");
                R(ref s, "And at those times, <E049><E003 8>what was the secondary assistant\r\ndoing?", "Et à ces moments-là, <E049><E003 8>que faisait la seconde\r\nassistante ?");
                R(ref s, "...Following this Japanese man's orders to adjust the\r\nlighting or pass him implements.", "...Elle obéissait aux ordres de ce Japonais pour ajuster\r\nl'éclairage ou lui passer des instruments.");
                R(ref s, "But that doesn't mean Mama <E049><E003 10><E025 1><E346>wasn't a vital part of the\r\nteam!", "Mais ça ne veut pas dire que Maman <E049><E003 10><E025 1><E346>n'était pas un élément\r\nessentiel de l'équipe !");
                R(ref s, "Q-<E049><E003 8><E331>Quite, <E049><E003 10>yes.<E049><E003 12> <E025 2><E338><E342>So would you kindly refrain from staring\r\nat my cheek like that?", "T-<E049><E003 8><E331>Tout à fait, <E049><E003 10>oui.<E049><E003 12> <E025 2><E338><E342>Alors auriez-vous l'obligeance de cesser\r\nde me fixer la joue de la sorte ?");
                R(ref s, "Professor Mikotoba, <E049><E003 10>think!<E049><E003 10> <E145 112 6><E003 6><E025 1><E332>Was there nothing at all that\r\nseemed out of place to you?", "Professeur Mikotoba, <E049><E003 10>réfléchissez !<E049><E003 10> <E145 112 6><E003 6><E025 1><E332>N'y a-t-il vraiment rien\r\nqui vous ait paru anormal ?");
                R(ref s, "Well...<E003 12><E025 3><E341>yes, <E049><E003 10><E025 2>there was, <E049><E003 8>as a matter of fact.", "Eh bien...<E003 12><E025 3><E341>si, <E049><E003 10><E025 2>en vérité, il y avait quelque chose.");
                return s;
            };

            // [10] BB\script\output\_sce04_c400_0020_eng#10
            entryTranslators[@"BB\script\output\_sce04_c400_0020_eng#10"] = (s) => {
                R(ref s, "In all of the previous four killings attributed to the\r\nProfessor...", "Dans les quatre meurtres précédents attribués au\r\nProfesseur...");
                R(ref s, "...the victims were killed by an enormous dog, <E049><E003 6>I believe?<E049><E003 12>\r\n<E025 3>Their throats were, <E049><E003 8><E341>well...<E003 14><E330>mauled?", "...les victimes ont été tuées par un chien énorme, <E049><E003 6>me semble-t-il ?<E049><E003 12>\r\n<E025 3>Leur gorge était, <E049><E003 8><E341>eh bien...<E003 14><E330>déchiquetée ?");
                R(ref s, "Correct.<E049><E003 12> <E025 2>And yet Lord van Zieks was stabbed.", "C'est exact.<E049><E003 12> <E025 2>Et pourtant, Lord Van Peers a été poignardé.");
                R(ref s, "Do, <E049><E003 8><E025 2>do you mean to say...", "Vou... <E049><E003 8><E025 2>voulez-vous dire que...");
                R(ref s, "...you think Lord Klint van Zieks may not in fact have\r\nbeen one of the Professor's victims?!", "...vous pensez que Lord Klint Van Peers n'était peut-être pas\r\nen réalité l'une des victimes du Professeur ?!");
                R(ref s, "There is no basis on which to doubt the findings of the\r\ninvestigations carried out at the time.", "Il n'y a aucun fondement permettant de douter des conclusions\r\ndes enquêtes menées à l'époque.");
                R(ref s, "Genshin Asogi confessed to all of his crimes upon his\r\narrest.", "Genshin Asogi a avoué tous ses crimes dès son\r\narrestation.");
                R(ref s, "He admitted to having taken the lives of all five members\r\nof the aristocracy.", "Il a admis avoir ôté la vie aux cinq membres\r\nde l'aristocratie.");
                R(ref s, "Yet the beast that was used to carry out the killings was\r\nnever identified.", "Pourtant, le fauve qui a servi à commettre ces meurtres n'a\r\njamais été identifié.");
                R(ref s, "No evidence was found to suggest that Genshin had ever\r\nkept a dog.", "Aucune preuve n'a permis d'établir que Genshin ait jamais\r\npossédé de chien.");
                R(ref s, "...A true hound of hell.", "...Un véritable chien des enfers.");
                return s;
            };

            // [11] BB\script\output\_sce04_c400_0020_eng#11
            entryTranslators[@"BB\script\output\_sce04_c400_0020_eng#11"] = (s) => {
                R(ref s, "But, <E049><E003 8>um...<E003 12><E025 2>you weren't actually present at the autopsy\r\nyourself, <E049><E003 8>were you, <E049><E003 6>Dr Gorey?", "Mais, <E049><E003 8>euh...<E003 12><E025 2>vous n'étiez pas vous-même présente à cette\r\nautopsie, <E049><E003 8>n'est-ce pas, <E049><E003 6>Dre Gorey ?");
                R(ref s, "Does that matter?", "Est-ce que ça a de l'importance ?");
                R(ref s, "Well, <E049><E003 8>I...<E003 12><E025 2>just wonder how useful your testimony can be\r\nin that case, <E049><E003 6>really.", "Eh bien, <E049><E003 8>je...<E003 12><E025 2>me demande juste à quel point votre témoignage peut être\r\nutile dans ce cas, <E049><E003 6>à vrai dire.");
                R(ref s, "I mean, <E049><E003 8><E025 2>it would be different if your mother, <E049><E003 6>Dr Sithe,<E049><E003 8>\r\nwere in the stand, <E049><E003 8><E025 3>but...", "Je veux dire, <E049><E003 8><E025 2>ce serait différent si votre mère, <E049><E003 6>la Dre Sithe,<E049><E003 8>\r\nétait à la barre, <E049><E003 8><E025 3>mais...");
                R(ref s, "I've read all the paperwork about the case!<E003 12>\r\n<E025 1><E345>And Mama's told me the story countless times!", "J'ai lu tous les dossiers sur cette affaire !<E003 12>\r\n<E025 1><E345>Et Maman m'a raconté l'histoire d'innombrables fois !");
                R(ref s, "The statement I just made <E003 10><E025 1><E346>is exactly what's written in the\r\nautopsy report!", "La déclaration que je viens de faire <E003 10><E025 1><E346>est exactement ce qui figure\r\ndans le rapport d'autopsie !");
                R(ref s, "I did confirm that myself at the time, <E049><E003 8>it's true.<E049><E003 10> Besides the\r\nstab wound, <E049><E003 6>there were no other signs of internal trauma.", "J'ai moi-même vérifié cela à l'époque, <E049><E003 8>c'est exact.<E049><E003 10> Hormis la\r\nplaie d'arme blanche, <E049><E003 6>il n'y avait aucun autre traumatisme interne.");
                R(ref s, "Mama told me all about it.", "Maman m'a tout raconté.");
                R(ref s, "She said there was nothing of note internally...", "Elle m'a dit qu'il n'y avait rien de notable à l'intérieur...");
                R(ref s, "...but they did find an amazing <E006>piece of evidence<E005>.<E049><E003 13>\r\n<E025 2><E238>Something unbelievable!", "...mais ils ont trouvé une stupéfiante <E006>pièce à conviction<E005>.<E049><E003 13>\r\n<E025 2><E238>Quelque chose d'incroyable !");
                R(ref s, "Unbelievable?<E049><E003 10> <E025 2>What do you mean?", "Incroyable ?<E049><E003 10> <E025 2>Que voulez-vous dire ?");
                R(ref s, "Come on, <E049><E003 8>Dr Gorey!<E049><E003 10>\r\n<E025 1><E145 112 7><E003 8><E332>What was it?", "Voyons, <E049><E003 8>Dre Gorey !<E049><E003 10>\r\n<E025 1><E145 112 7><E003 8><E332>Qu'est-ce que c'était ?");
                return s;
            };

            // [12] BB\script\output\_sce04_c400_0020_eng#12
            entryTranslators[@"BB\script\output\_sce04_c400_0020_eng#12"] = (s) => {
                R(ref s, "What exactly was it, though?<E049><E003 10> <E145 1 85><E003 8>\r\n<E025 2><E330>What does ‘beautiful but dangerous’ mean?", "Qu'est-ce que c'était exactement, au juste ?<E049><E003 10> <E145 1 85><E003 8>\r\n<E025 2><E330>Que veut dire « magnifique mais dangereuse » ?");
                R(ref s, "...it was sparkly and round, <E049><E003 6>with a hole...<E049><E003 12><E025 2>as if it might slip\r\nover a finger perhaps.", "...c'était étincelant et rond, <E049><E003 6>avec un trou...<E049><E003 12><E025 2>comme pour glisser\r\nautour d'un doigt, peut-être.");
                R(ref s, "It was <E006>a ring<E005>.<E049><E003 10>\r\n<E025 3><E145 46 74><E118 46 0.8><E003 10><E330><E092 6>Belonging to Genshin Asogi.", "C'était <E006>une bague<E005>.<E049><E003 10>\r\n<E025 3><E145 46 74><E118 46 0.8><E003 10><E330><E092 6>Appartenant à Genshin Asogi.");
                R(ref s, "M-<E049><E003 8><E025 3>My father's ring...<E003 15><E025 1><E606><E145 112 8>was inside the victim's stomach?!", "La... <E049><E003 8><E025 3>la bague de mon père...<E003 15><E025 1><E606><E145 112 8>était dans l'estomac de la victime ?!");
                R(ref s, "At the time, <E049><E003 6><E145 46 64><E118 46 0.7><E003 6><E025 2>Genshin wore a large ring on the digitus\r\nquartus of his left hand –<E049><E003 6> <E025 3>the fourth <E049><E003 6>or ‘ring’ finger.", "À l'époque, <E049><E003 6><E145 46 64><E118 46 0.7><E003 6><E025 2>Genshin portait une grosse bague au quatrième doigt\r\nde sa main gauche –<E049><E003 6> <E025 3>l'annulaire.");
                R(ref s, "I'd understood it was some sort of keepsake.", "J'avais cru comprendre qu'il s'agissait d'un souvenir.");
                R(ref s, "When my father left Japan for London sixteen years ago,<E049><E003 8>\r\nI was eight years old.", "Quand mon père a quitté le Japon pour Londres il y a seize ans,<E049><E003 8>\r\nj'avais huit ans.");
                R(ref s, "But I remember that ring.", "Mais je me souviens de cette bague.");
                R(ref s, "My father's possessions were sent to our family home in\r\nJapan after his death, <E049><E003 8><E025 3>but the ring wasn't among them.", "Les effets personnels de mon père ont été renvoyés à notre foyer familial au\r\nJapon après sa mort, <E049><E003 8><E025 3>mais la bague n'en faisait pas partie.");
                R(ref s, "Obviously not.<E049><E003 12>\r\nIt was a key piece of evidence.", "Évidemment non.<E049><E003 12>\r\nC'était une pièce à conviction déterminante.");
                R(ref s, "It remains under lock and key in the stores at Scotland\r\nYard to this day.", "Elle demeure sous clé dans la salle des scellés de Scotland\r\nYard jusqu'à ce jour.");
                R(ref s, "After the autopsy, <E049><E003 8>Genshin was summoned by the police\r\nto check for the presence of his ring.", "Après l'autopsie, <E049><E003 8>Genshin a été convoqué par la police\r\npour vérifier la présence de sa bague.");
                R(ref s, "It wasn't on his hand of course.<E049><E003 10> <E025 3>Moreover...<E003 14><E239><E025 3>there were\r\n<E006>deep abrasions<E005> on his finger where it had been pulled off.", "Elle n'était pas à son doigt bien sûr.<E049><E003 10> <E025 3>De plus...<E003 14><E239><E025 3>il y avait\r\nde <E006>profondes écorchures<E005> à l'endroit où on la lui avait arrachée.");
                R(ref s, "...They arrested the man there and then, <E049><E003 10><E025 3>right before my\r\neyes.", "...Ils ont arrêté cet homme sur-le-champ, <E049><E003 10><E025 3>sous mes yeux.");
                R(ref s, "How could they?!", "Comment ont-ils pu ?!");
                R(ref s, "I brought the ring <E049><E003 8><E164 42 72 1 2 6 0 0 1><E139 42><E025 2>along with me today.", "J'ai apporté la bague <E049><E003 8><E164 42 72 1 2 6 0 0 1><E139 42><E025 2>avec moi aujourd'hui.");
                R(ref s, "Here it is.<E049><E003 12> <E025 2>A bit dusty from years in the stores.", "La voici.<E049><E003 12> <E025 2>Un peu poussiéreuse après tant d'années aux scellés.");
                R(ref s, "Good gracious!<E049><E003 12> <E025 2>Yes, <E049><E003 8>that's it.<E049><E003 12><E060 0 161 1 0>\r\n<E025 2>I haven't seen that in ten long years...", "Grands dieux !<E049><E003 12> <E025 2>Oui, <E049><E003 8>c'est bien elle.<E049><E003 12><E060 0 161 1 0>\r\n<E025 2>Je ne l'avais pas vue depuis dix longues années...");
                R(ref s, "And...<E049><E003 12><E025 2><E341>that was found inside the victim's stomach?", "Et...<E049><E003 12><E025 2><E341>cela a été trouvé dans l'estomac de la victime ?");
                R(ref s, "I...<E049><E003 16> <E025 2>Yes, <E049><E003 8>I'm afraid so.", "Je...<E049><E003 16> <E025 2>Oui, <E049><E003 8>je le crains.");
                R(ref s, "You hesitated there, <E049><E003 6>Professor Mikotoba.<E049><E003 10><E145 1 66><E118 1 0.9><E003 12>\r\n<E025 3>...Should we read something into that?", "Vous avez hésité, <E049><E003 6>professeur Mikotoba.<E049><E003 10><E145 1 66><E118 1 0.9><E003 12>\r\n<E025 3>...Devrions-nous y voir un sous-entendu ?");
                R(ref s, "Ah, <E049><E003 8>well...<E049><E003 15>\r\n<E025 2>It's just that thinking back now...", "Ah, <E049><E003 8>eh bien...<E049><E003 15>\r\n<E025 2>C'est juste qu'en y repensant aujourd'hui...");
                R(ref s, "...I <E006>didn't actually witness<E005> the moment it was extracted\r\nfrom the victim's body.", "...je n'ai <E006>pas assisté de mes yeux<E005> au moment où elle a été extraite\r\ndu corps de la victime.");
                R(ref s, "Oh my!<E049><E003 15> <E025 3><E341>Really?", "Bonté divine !<E049><E003 15> <E025 3><E341>Vraiment ?");
                R(ref s, "At that precise moment, <E049><E003 6><E145 46 74><E003 6>Dr Wilson had asked me to fetch\r\nhim a new scalpel, <E003 4>you see.", "À cet instant précis, <E049><E003 6><E145 46 74><E003 6>le Dr Wilson m'avait demandé de lui\r\nrapporter un nouveau scalpel, <E003 4>voyez-vous.");
                R(ref s, "...the removal of historic evidence from the stores\r\nrequires my consent, <E049><E003 8><E025 3>does it not?", "...le retrait de pièces à conviction historiques des scellés\r\nexige mon consentement, <E049><E003 8><E025 3>n'est-ce pas ?");
                R(ref s, "However it came to be here, <E049><E003 10><E025 1><E335>the court cannot deny that\r\nthis is crucial evidence for today's proceedings.", "Quelle que soit la manière dont elle est arrivée ici, <E049><E003 10><E025 1><E335>le tribunal ne peut nier\r\nqu'il s'agit d'une preuve capitale pour l'audience du jour.");
                R(ref s, "Very well, <E049><E003 8><E025 2>you may submit it.", "Fort bien, <E049><E003 8><E025 2>vous pouvez la déposer.");
                R(ref s, "Mr Asogi's ring has been\r\nentered into the Court Record.", "La bague de M. Asogi a été\r\najoutée au dossier de l'affaire.");
                R(ref s, "It's not the sort of ring normally seen in Japan.<E049><E003 10>\r\n<E025 3><E007>(They almost look like claws protecting that jewel...)", "Ce n'est pas le genre de bague qu'on voit d'ordinaire au Japon.<E049><E003 10>\r\n<E025 3><E007>(On dirait presque des serres protégeant ce joyau...)");
                R(ref s, "We must examine it very carefully, <E049><E003 6>Mr Naruhodo.<E049><E003 12>\r\n<E025 1>Very carefully indeed!", "Nous devons l'examiner très attentivement, <E049><E003 6>monsieur Naruhodo.<E049><E003 12>\r\n<E025 1>Très attentivement, en vérité !");
                return s;
            };

            // [13] BB\script\output\_sce04_c400_0020_eng#13
            entryTranslators[@"BB\script\output\_sce04_c400_0020_eng#13"] = (s) => {
                R(ref s, "By beautiful and dangerous evidence, <E049><E003 8><E145 1 0><E118 1 1.2><E060 0 161 1 0><E003 8><E025 2>you mean this large\r\nring, <E049><E003 6>obviously.", "Par preuve magnifique et dangereuse, <E049><E003 8><E145 1 0><E118 1 1.2><E060 0 161 1 0><E003 8><E025 2>vous voulez dire cette imposante\r\nbague, <E049><E003 6>évidemment.");
                R(ref s, "That's right.<E049><E003 10> <E025 2>Pulled from the victim's stomach once it had\r\nbeen sliced open nicely.", "C'est bien ça.<E049><E003 10> <E025 2>Retirée de l'estomac de la victime après qu'on l'a\r\nsoigneusement incisé.");
                R(ref s, "It was my brother's final move before he perished.", "Ce fut le dernier geste de mon frère avant de succomber.");
                R(ref s, "An ingenious one, <E049><E003 12><E330>to leave us <E006>a clue<E005> by which to identify\r\nhis killer.", "Un geste ingénieux, <E049><E003 12><E330>pour nous laisser <E006>un indice<E005> permettant d'identifier\r\nson meurtrier.");
                R(ref s, "He must have ripped the ring from Genshin's finger with\r\nhis teeth...", "Il a dû arracher la bague du doigt de Genshin avec\r\nses dents...");
                R(ref s, "...before swallowing it to keep it from being retrieved.<E049><E003 8><E145 46 64><E003 10>\r\n<E025 2>...That was the prevailing hypothesis at the time.", "...avant de l'avaler pour empêcher qu'on la récupère.<E049><E003 8><E145 46 64><E003 10>\r\n<E025 2>...C'était la thèse dominante à l'époque.");
                R(ref s, "W-<E049><E003 8>With his teeth?!", "A... <E049><E003 8>Avec ses dents ?!");
                R(ref s, "On his arrest, <E049><E003 8><E025 2>Genshin Asogi's ring finger on his left hand\r\nwas found to be badly wounded.", "Lors de son arrestation, <E049><E003 8><E025 2>l'annulaire de la main gauche de Genshin Asogi\r\nétait gravement blessé.");
                R(ref s, "...Evidence of my brother's final struggle against the man.", "...Preuve de l'ultime lutte de mon frère contre cet individu.");
                R(ref s, "All for this ring...?", "Tout cela pour cette bague... ?");
                return s;
            };

            // [14] BB\script\output\_sce04_c400_0020_eng#14
            entryTranslators[@"BB\script\output\_sce04_c400_0020_eng#14"] = (s) => {
                R(ref s, "And that was the decisive piece of evidence that led to\r\nGenshin Asogi's arrest?", "Et c'est la pièce décisive qui a mené à\r\nl'arrestation de Genshin Asogi ?");
                R(ref s, "After further investigations by Scotland Yard, <E049><E003 8><E025 3>the man\r\nadmitted to his crimes.", "Après de plus amples investigations menées par Scotland Yard, <E049><E003 8><E025 3>l'homme\r\na avoué ses crimes.");
                R(ref s, "That's a lie! <E049><E003 14><E025 1><E332>My father was no killer!", "C'est un mensonge ! <E049><E003 14><E025 1><E332>Mon père n'était pas un meurtrier !");
                R(ref s, "Barok van Zieks!<E049><E003 12> <E025 2>It was you!<E049><E003 12> <E342><E025 1>You twisted the truth to suit\r\nyour purposes!", "Drake Van Peers !<E049><E003 12> <E025 2>C'était vous !<E049><E003 12> <E342><E025 1>Vous avez déformé la vérité pour servir\r\nvos desseins !");
                R(ref s, "Your hatred of me doesn't change the facts that were\r\nestablished ten years ago.", "Votre haine envers moi ne change rien aux faits qui furent\r\nétablis il y a dix ans.");
                R(ref s, "My brother Klint had closed in on the Professor.", "Mon frère Klint avait cerné le Professeur de près.");
                R(ref s, "In the end, <E049><E003 8><E025 2>he exposed the man and put a stop to his\r\nlethal rampage.", "À la fin, <E049><E003 8><E025 2>il a démasqué cet individu et mis fin à sa\r\nfolie meurtrière.");
                R(ref s, "...In the way only a man of my brother's calibre could.", "...De la façon dont seul un homme de la trempe de mon frère était capable.");
                return s;
            };

            // [15] BB\script\output\_sce04_c400_0020_eng#15
            entryTranslators[@"BB\script\output\_sce04_c400_0020_eng#15"] = (s) => {
                R(ref s, "(That's everything...<E003 12><E025 3>is it?)", "(C'est tout ce qu'il y avait...<E003 12><E025 3>vraiment ?)");
                R(ref s, "Poor Father.<E049><E003 8> <E025 3><E145 9 8><E003 5>He looks so troubled.", "Pauvre Père.<E049><E003 8> <E025 3><E145 9 8><E003 5>Il a l'air si tourmenté.");
                R(ref s, "Perhaps because ten years ago...<E049><E003 14><E025 2><E330>something happened\r\nthat's been weighing on his mind.", "Peut-être parce qu'il y a dix ans...<E049><E003 14><E025 2><E330>il s'est passé quelque chose\r\nqui n'a cessé de peser sur sa conscience.");
                R(ref s, "‘I couldn't say’ <E003 6>were his words.<E003 14> <E025 1><E345>That phrasing was very\r\ndeliberate, I'm sure!", "« Je ne saurais l'affirmer » <E003 6>furent ses mots.<E003 14> <E025 1><E345>Cette formulation était très\r\ndélibérée, j'en suis sûr !");
                R(ref s, "I wonder if he's had his suspicions all these years.", "Je me demande s'il a eu des soupçons durant toutes ces années.");
                R(ref s, "If that's the case, <E003 8>we need to use this cross-examination\r\nto prove what really happened...", "Si c'est le cas, <E003 8>nous devons utiliser ce contre-interrogatoire\r\npour prouver ce qui s'est réellement passé...");
                R(ref s, "...and remove any trace of doubt.", "...et dissiper le moindre doute.");
                R(ref s, "If we could establish that Kazuma-sama's claim of\r\nfabricated evidence was true...", "Si nous pouvions établir que l'affirmation de maître Kazuma sur la falsification\r\ndes preuves était fondée...");
                R(ref s, "We can't shy away from this now.", "Nous ne pouvons plus reculer maintenant.");
                R(ref s, "Even if what we might uncover could lead to total\r\ncalamity.", "Même si ce que nous pourrions découvrir menait à un désastre\r\ntotal.");
                R(ref s, "Don't worry, Mr Naruhodo.<E049><E003 10>\r\n<E025 2>I'll be right beside you, <E049><E003 6><E025 1><E164 9 15 1 2 8 0 1 1><E139 9>whatever may happen!", "Ne vous inquiétez pas, monsieur Naruhodo.<E049><E003 10>\r\n<E025 2>Je serai à vos côtés, <E049><E003 6><E025 1><E164 9 15 1 2 8 0 1 1><E139 9>quoi qu'il arrive !");
                return s;
            };

            // [16] BB\script\output\_sce04_c400_0020_eng#16
            entryTranslators[@"BB\script\output\_sce04_c400_0020_eng#16"] = (s) => {
                R(ref s, "Is something wrong, <E049><E003 6><E025 3>Dr Gorey?", "Il y a un problème, <E049><E003 6><E025 3>Dre Gorey ?");
                R(ref s, "Did the last statement give you pause for thought,\r\nperhaps?", "La dernière déposition vous a-t-elle interpellée,\r\npeut-être ?");
                R(ref s, "...Well, <E049><E003 10>something did just come to mind.", "...Eh bien, <E049><E003 10>une pensée m'a traversé l'esprit.");
                R(ref s, "If you Easterners come from the other side of the world,<E049><E003 10>\r\n<E330>are your internal organs all flipped?", "Si vous autres Orientaux venez de l'autre bout de la terre,<E049><E003 10>\r\n<E330>est-ce que tous vos organes internes sont inversés ?");
                R(ref s, "I'm desperate to look.", "Je meurs d'envie d'y jeter un œil.");
                R(ref s, "...Strictly speaking, <E049><E003 8>that's not really related to the\r\ntestimony, <E049><E003 6>is it?", "...À proprement parler, <E049><E003 8>ça n'a pas vraiment de rapport avec la\r\ndéposition, <E049><E003 6>n'est-ce pas ?");
                R(ref s, "Ready for the first incision?", "Prêt pour la première incision ?");
                R(ref s, "NO!", "NON !");
                return s;
            };

            // [17] BB\script\output\_sce04_c400_0020_eng#17
            entryTranslators[@"BB\script\output\_sce04_c400_0020_eng#17"] = (s) => {
                R(ref s, "Professor Mikotoba!", "Professeur Mikotoba !");
                R(ref s, "Yeees?<E049><E003 8> <E025 2>What can I do for you, Naruhodo?", "Ouuui ?<E049><E003 8> <E025 2>Que puis-je faire pour vous, Naruhodo ?");
                R(ref s, "Did something about that last statement bother you in\r\nsome way?", "Quelque chose dans cette dernière déclaration vous chiffonne-t-il\r\nd'une quelconque façon ?");
                R(ref s, "I feel as though it might have done, <E049><E003 6>as it happens.", "J'ai bien l'impression que oui, <E049><E003 6>à vrai dire.");
                R(ref s, "But you startled me so much, <E049><E003 6>I've clean forgotten what I\r\nwas thinking.", "Mais vous m'avez tellement surpris <E049><E003 6>que j'en ai complètement oublié\r\nce que je pensais.");
                R(ref s, "Perhaps try to remember for next time, then.", "Essayez peut-être de vous en souvenir pour la prochaine fois, alors.");
                R(ref s, "And perhaps you could try to remember not to holler\r\nnext time, <E169 46 0><E003 6>hm?<E169 46 3>", "Et peut-être pourriez-vous essayer de vous souvenir de ne pas hurler\r\nla prochaine fois, <E169 46 0><E003 6>hum ?<E169 46 3>");
                return s;
            };

            // [18] BB\script\output\_sce04_c400_0020_eng#18
            entryTranslators[@"BB\script\output\_sce04_c400_0020_eng#18"] = (s) => {
                R(ref s, "Lord van Zieks!", "Lord Van Peers !");
                R(ref s, "Let me guess:<E049><E003 10> <E238><E025 2>is there something about the witness's last\r\nstatement that troubles me?", "Laissez-moi deviner :<E049><E003 10> <E238><E025 2>y a-t-il quelque chose dans la dernière déclaration\r\ndu témoin qui me tourmente ?");
                R(ref s, "Is that what you wish to ask?", "Est-ce là ce que vous souhaitez me demander ?");
                R(ref s, "Y-<E049><E003 6>Yes...<E003 12> Exactly...<E049><E003 8><E145 1 64><E003 8>\r\n<E025 2>You're very perceptive.", "O... <E049><E003 6>Oui...<E003 12> Exactement...<E049><E003 8><E145 1 64><E003 8>\r\n<E025 2>Vous êtes très perspicace.");
                R(ref s, "Whereas you...<E003 12><E025 3>would appear not to be.", "Tandis que vous...<E003 12><E025 3>semblez ne point l'être.");
                R(ref s, "You really need to learn how to read your fellow man...<E049><E003 12>\r\n<E025 3>my Nipponese friend.", "Il vous faudrait vraiment apprendre à percer vos semblables à jour...<E049><E003 12>\r\n<E025 3>mon cher ami nippon.");
                R(ref s, "(...Read them...<E003 12>or ‘reap’ them?)", "(...Les percer à jour...<E003 12>ou les faucher ?)");
                return s;
            };

            // [19] BB\script\output\_sce04_c400_0020_eng#27
            entryTranslators[@"BB\script\output\_sce04_c400_0020_eng#27"] = (s) => {
                R(ref s, "We've wasted enough time!", "Nous avons perdu assez de temps !");
                R(ref s, "It's clear to me <E049><E003 8><E025 2>that any further discussion of this case will\r\nbe fruitless.", "Il m'apparaît clairement <E049><E003 8><E025 2>que toute nouvelle discussion sur cette affaire sera\r\nstérile.");
                R(ref s, "Barok van Zieks, <E049><E003 8><E025 2>I would like to think that however\r\nmisguided...", "Drake Van Peers, <E049><E003 8><E025 2>j'aimerais croire que, si fourvoyé fussiez-vous...");
                R(ref s, "...you acted out of a sense of justice nonetheless.<E049><E003 12>\r\n<E025 3>Though it pains me to have reached this conclusion...", "...vous avez néanmoins agi par sens de la justice.<E049><E003 12>\r\n<E025 3>Bien qu'il me soit douloureux d'en arriver à cette conclusion...");
                R(ref s, "No!<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Wait, My Lord!", "Non !<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Attendez, Votre Honneur !");
                R(ref s, "In accordance with the findings of this court, <E049><E003 6><E025 3>I hereby\r\npronounce the defendant, <E049><E003 6><E025 3>Barok van Zieks...", "Conformément aux conclusions de ce tribunal, <E049><E003 6><E025 3>je déclare\r\nici l'accusé, <E049><E003 6><E025 3>Drake Van Peers...");
                R(ref s, "That concludes business.<E049><E003 10>\r\n<E025 2>Court is adjourned!", "Ceci clôt les débats.<E049><E003 10>\r\n<E025 2>L'audience est levée !");
                return s;
            };

            // [20] BB\script\output\_sce04_c400_0030_eng#2
            entryTranslators[@"BB\script\output\_sce04_c400_0030_eng#2"] = (s) => {
                R(ref s, "The court has heard that the ring was extracted from the\r\nvictim's stomach.", "Le tribunal a entendu que la bague a été extraite de l'estomac\r\nde la victime.");
                R(ref s, "But you <E006>didn't actually see<E005> it being removed, <E049><E003 4><E145 1 7><E118 1 0.7><E003 10>did you,<E003 4>\r\nProfessor Mikotoba?", "Mais vous ne l'avez <E006>pas vue de vos propres yeux<E005> être retirée, <E049><E003 4><E145 1 7><E118 1 0.7><E003 10>n'est-ce pas,<E003 4>\r\nprofesseur Mikotoba ?");
                R(ref s, "That's right.<E049><E003 10> <E145 46 64><E003 6><E025 2>As I said in my testimony before...", "C'est exact.<E049><E003 10> <E145 46 64><E003 6><E025 2>Comme je l'ai mentionné plus tôt...");
                R(ref s, "...at that moment, <E049><E003 8>I was fetching a replacement scalpel\r\nthat Dr Wilson had requested.", "...à ce moment-là, <E049><E003 8>j'étais allé chercher un autre scalpel\r\nque le Dr Wilson m'avait réclamé.");
                R(ref s, "In other words, <E049><E003 4><E145 1 0><E149 1 0 8><E003 15><E025 3>you can neither confirm nor deny...", "En d'autres termes, <E049><E003 4><E145 1 0><E149 1 0 8><E003 15><E025 3>vous ne pouvez ni confirmer ni infirmer...");
                R(ref s, "...whether this ring in fact <E049><E003 6><E145 1 21><E003 15><E025 2><E330>really came from the victim's\r\nstomach or not.", "...si cette bague <E049><E003 6><E145 1 21><E003 15><E025 2><E330>provenait réellement ou non de l'estomac\r\nde la victime.");
                R(ref s, "What are you suggesting, Counsel?", "Qu'insinuez-vous, Maître ?");
                R(ref s, "That the ring was never in the victim's stomach to begin\r\nwith!", "Que cette bague n'a jamais été dans l'estomac de la victime\r\npour commencer !");
                R(ref s, "It's entirely feasible that Dr Wilson <E006>fabricated<E005> that detail\r\nabout the autopsy!", "Il est tout à fait plausible que le Dr Wilson ait <E006>fabriqué<E005> ce détail\r\nde l'autopsie !");
                R(ref s, "What are you saying?!<E049><E003 15><E145 112 7><E117 112 15><E003 10>\r\n<E025 2><E045>That Dr Wilson...", "Qu'êtes-vous en train de dire ?!<E049><E003 15><E145 112 7><E117 112 15><E003 10>\r\n<E025 2><E045>Que le Dr Wilson...");
                R(ref s, "That Dr Wilson was in possession of the ring in advance,<E049><E003 8>\r\nafter it was somehow stolen from Mr Asogi...", "Que le Dr Wilson était en possession de la bague au préalable,<E049><E003 8>\r\naprès qu'elle a été dérobée d'une façon ou d'une autre à M. Asogi...");
                R(ref s, "...and he produced it during the procedure, <E003 4>pretending to\r\nhave found it <E006>there and then<E005> in the victim's stomach.", "...et qu'il l'a sortie pendant l'intervention, <E003 4>faisant mine de\r\nl'avoir trouvée <E006>à cet instant même<E005> dans l'estomac de la victime.");
                R(ref s, "Supposition at best!<E049><E003 12> <E025 2>What possible evidence do you have<E049><E003 12>\r\n<E025 1><E332>to support such a rash claim?!", "Simple supposition au mieux !<E049><E003 12> <E025 2>Quelle preuve pourriez-vous bien avoir<E049><E003 12>\r\n<E025 1><E332>pour étayer une affirmation si téméraire ?!");
                R(ref s, "This evidence...<E003 12>right here.", "Cette preuve...<E003 12>ici même.");
                R(ref s, "That's <E049><E003 5><E164 112 7 1 2 6 0 1 1><E139 112><E025 1>the autopsy report!", "C'est <E049><E003 5><E164 112 7 1 2 6 0 1 1><E139 112><E025 1>le rapport d'autopsie !");
                R(ref s, "It's explicit in that report, <E003 4>Counsel.", "C'est pourtant explicite dans ce rapport, <E003 4>Maître.");
                R(ref s, "Other than the ring, <E049><E003 6>nothing unusual was noted internally.<E049><E003 12>\r\n<E025 2><E341>So I'm not sure how you intend to prove your point.", "Hormis la bague, <E049><E003 6>rien d'anormal n'a été constaté à l'intérieur.<E049><E003 12>\r\n<E025 2><E341>Je ne vois donc pas comment vous comptez prouver vos dires.");
                R(ref s, "You've already done it for me, <E003 4>My Lord.<E049><E003 13><E145 1 0><E003 10>\r\n<E025 2><E330>The lack of internal injury says it all.", "Vous venez de le faire pour moi, <E003 4>Votre Honneur.<E049><E003 13><E145 1 0><E003 10>\r\n<E025 2><E330>L'absence de blessure interne dit tout.");
                R(ref s, "To swallow a ring of this size <E049><E003 10><E025 2>would require considerable\r\neffort and determination.", "Avaler une bague de cette taille <E049><E003 10><E025 2>exigerait un effort et une\r\ndétermination considérables.");
                R(ref s, "And in addition to its size, <E049><E003 10>there are the sharp claws\r\naround the gemstone to contend with.", "Et outre sa taille, <E049><E003 10>il faut compter avec les griffes acérées\r\nqui enserrent la pierre précieuse.");
                R(ref s, "My brother was a determined man.<E049><E003 10> <E025 2>And on the brink of\r\ndeath, <E049><E003 6><E025 3>even more so, <E049><E003 8>I'm sure.", "Mon frère était un homme déterminé.<E049><E003 10> <E025 2>Et à l'article de\r\nla mort, <E049><E003 6><E025 3>plus encore, <E049><E003 8>j'en suis convaincu.");
                R(ref s, "He would have stopped at nothing to ensure that evil\r\nkiller was brought to justice.", "Il n'aurait reculé devant rien pour que ce sinistre\r\ntueur soit traduit en justice.");
                R(ref s, "But if he really had swallowed that enormous ring...", "Mais s'il avait véritablement avalé cette énorme bague...");
                R(ref s, "...it's inconceivable that no <E006>traces<E005> <E049><E003 10><E164 1 8 1 2 5 0 2 1><E139 1><E025 1>of its passage down his\r\nthroat would have remained as internal trauma!", "...il est inconcevable qu'aucune <E006>trace<E005> <E049><E003 10><E164 1 8 1 2 5 0 2 1><E139 1><E025 1>de son passage dans sa\r\ngorge n'ait subsisté sous la forme de traumatismes internes !");
                R(ref s, "And there you've arrived at the sticking point.", "Et vous voilà arrivé au cœur du problème.");
                R(ref s, "That's precisely why I <E006>had my doubts<E005> about the findings\r\nmyself ten years ago.", "C'est précisément la raison pour laquelle j'<E006>avais moi-même des doutes<E005>\r\nsur ces constatations il y a dix ans.");
                R(ref s, "Then why didn't you say something <E341>at the time?!", "Alors pourquoi n'avoir rien dit <E341>à l'époque ?!");
                R(ref s, "I did.<E049><E003 15> I still remember the conversation I had with\r\nDr Wilson in the laboratory that day.", "Je l'ai fait.<E049><E003 15> Je me rappelle encore la conversation que j'ai eue\r\navec le Dr Wilson dans le laboratoire ce jour-là.");
                R(ref s, "Look at this!", "Regardez-moi ça !");
                R(ref s, "Now this is a very curious thing to find in a man's\r\nstomach, <E003 6>wouldn't you say?", "Voilà une bien curieuse trouvaille dans l'estomac d'un homme,\r\n<E003 6>ne trouvez-vous pas ?");
                R(ref s, "But...<E003 14><E238>isn't that rather peculiar, <E003 6>Dr Wilson?", "Mais...<E003 14><E238>n'est-ce pas particulièrement étrange, <E003 6>Dr Wilson ?");
                R(ref s, "What's that now, <E003 6><E341>Mikotoba?", "Qu'y a-t-il, <E003 6><E341>Mikotoba ?");
                R(ref s, "Well, <E003 8><E025 2>if he swallowed a ring of that size, <E003 6>with those sharp\r\nmetal claws that it has...", "Eh bien, <E003 8><E025 2>s'il avait avalé une bague de cette dimension, <E003 6>avec ses griffes\r\nde métal acérées...");
                R(ref s, "...surely you'd expect to see damage to the throat and\r\noesophagus?<E003 12> Torn mucous membranes at the very least.", "...ne devrait-on pas s'attendre à des lésions dans la gorge et\r\nl'œsophage ?<E003 12> Des muqueuses déchirées pour le moins.");
                R(ref s, "Doctor Mikotoba, <E003 8>may I remind you...", "Docteur Mikotoba, <E003 8>puis-je vous rappeler...");
                R(ref s, "...that I have vastly more experience than you.", "...que j'ai infiniment plus d'expérience que vous.");
                R(ref s, "I'm, <E003 12>I'm terribly sorry.", "Je... <E003 12>je suis sincèrement navré.");
                R(ref s, "I can think of plenty of ways to explain why no injuries\r\nwould be seen.", "Je peux imaginer d'innombrables explications à l'absence\r\nde lésions visibles.");
                R(ref s, "No, <E003 8>let's say this:<E003 12> <E025 3><E239>‘The victim would appear to have\r\ningested the item as evidence to identify his assailant.’", "Non, <E003 8>écrivons plutôt ceci :<E003 12> <E025 3><E239>« La victime semble avoir\r\ningéré l'objet comme preuve afin d'identifier son agresseur. »");
                R(ref s, "Go ahead!<E003 12> <E025 1><E341>Write it down!", "Allez-y !<E003 12> <E025 1><E341>Notez-le !");
                return s;
            };

            // [21] BB\script\output\_sce04_c400_0040_eng#2
            entryTranslators[@"BB\script\output\_sce04_c400_0040_eng#2"] = (s) => {
                R(ref s, "So I was right!<E049><E003 16> <E025 2><E238>Dr Wilson deliberately fabricated the\r\nresults of the autopsy to implicate my father!", "J'avais donc raison !<E049><E003 16> <E025 2><E238>Le Dr Wilson a délibérément fabriqué les\r\nrésultats de l'autopsie pour accuser mon père !");
                R(ref s, "I'm disappointed, <E049><E003 6>Counsel.<E049><E003 14>\r\nThat argument is nothing more than speculation.", "Je suis déçu, <E049><E003 6>Maître.<E049><E003 14>\r\nCet argument ne repose sur rien d'autre que des spéculations.");
                R(ref s, "Dr Wilson was Britain's leading authority on forensic\r\nscience and autopsy work.", "Le Dr Wilson était la plus grande sommité britannique en matière\r\nde médecine légale et d'autopsies.");
                R(ref s, "There is no scientific basis on which to doubt the man's\r\nexpert opinion.", "Il n'y a aucun fondement scientifique pour douter de l'avis\r\nd'un tel expert.");
                R(ref s, "Pardon the interruption, <E049><E003 8>My Lord, <E049><E003 10><E025 3>but...", "Pardonnez cette interruption, <E049><E003 8>Votre Honneur, <E049><E003 10><E025 3>mais...");
                R(ref s, "...damage to the mucous membranes of the throat is easily\r\nidentified <E049><E003 6><E025 3>even in living subjects.", "...des lésions sur les muqueuses de la gorge sont aisément\r\nrepérables, <E049><E003 6><E025 3>même chez un sujet vivant.");
                R(ref s, "Using a device called an ‘endoscope’, <E049><E003 8>recently\r\ndemonstrated in practical use in France.", "Grâce à un instrument appelé « endoscope », <E049><E003 8>dont l'usage pratique\r\na été récemment démontré en France.");
                R(ref s, "I want one!<E049><E003 12>\r\n<E025 2>...The government can pay.", "J'en veux un !<E049><E003 12>\r\n<E025 2>...Le gouvernement peut payer.");
                R(ref s, "I don't think so!<E049><E003 18>\r\n<E025 3>And Dr Gorey...", "Certainement pas !<E049><E003 18>\r\n<E025 3>Et Dre Gorey...");
                R(ref s, "...rest assured that your removal of evidence from the\r\nstores without permission will not go unpunished.", "...soyez assurée que votre soustraction de scellés sans\r\nautorisation ne restera point impunie.");
                R(ref s, "We open up the dead to find the truth.", "Nous ouvrons les défunts pour découvrir la vérité.");
                R(ref s, "But Mama...<E003 20> <E025 2>She chose to stitch her corpses up...<E049><E003 15><E025 3>with all\r\nher secrets inside...", "Mais Maman...<E003 20> <E025 2>Elle a choisi de recoudre ses cadavres...<E049><E003 15><E025 3>avec tous\r\nses secrets à l'intérieur...");
                R(ref s, "That's wrong.", "C'est mal.");
                R(ref s, "Dr Gorey...<E003 15>\r\n<E025 3><E007>(It's looking as though...)", "Dre Gorey...<E003 15>\r\n<E025 3><E007>(On dirait bien que...)");
                R(ref s, "(...she's chosen to walk a different path to her ‘mama’.)", "(...elle a choisi de suivre une autre voie que sa « maman ».)");
                R(ref s, "Yes...<E003 16><E239><E025 3>the ring.", "Oui...<E003 16><E239><E025 3>la bague.");
                R(ref s, "What about the ring?", "Qu'a-t-elle donc, cette bague ?");
                R(ref s, "I've just remembered something.<E049><E003 10><E145 18 0><E118 18 0.65><E003 20>\r\n<E025 2>An earlier incident.", "Je viens de me remémorer quelque chose.<E049><E003 10><E145 18 0><E118 18 0.65><E003 20>\r\n<E025 2>Un incident antérieur.");
                R(ref s, "What incident?", "Quel incident ?");
                R(ref s, "The one I recounted to you before.<E049><E003 14>\r\n<E025 3>About a memory I have...", "Celui que je vous ai déjà relaté.<E049><E003 14>\r\n<E025 3>Ce souvenir qui me hante...");
                R(ref s, "...of Genshin Asogi saving my life.", "...où Genshin Asogi m'a sauvé la vie.");
                R(ref s, "What?!<E049><E003 20> <E025 3>My, <E049><E003 8>my father...<E003 12><E025 2><E341>saved YOUR life?", "Quoi ?!<E049><E003 20> <E025 3>Mon... <E049><E003 8>mon père...<E003 12><E025 2><E341>vous a sauvé la vie ?");
                R(ref s, "It was ten years ago, <E049><E003 10><E025 3>on a foggy night.", "C'était il y a dix ans, <E049><E003 10><E025 3>par une nuit brumeuse.");
                R(ref s, "Genshin and I were walking down some back streets at a\r\nlate hour.", "Genshin et moi marchions dans des ruelles sombres à une\r\nheure tardive.");
                R(ref s, "All of a sudden...", "Tout à coup...");
                R(ref s, "Don't make a peep!<E003 15>\r\n<E042><CNTR><E025 1>You're comin' with us!", "Pas un bruit !<E003 15>\r\n<E042><CNTR><E025 1>Vous venez avec nous !");
                R(ref s, "All of our assailants were armed with pistols,<E049><E003 8> <E025 2>their faces\r\nobscured by scarves.", "Tous nos assaillants étaient armés de pistolets,<E049><E003 8> <E025 2>leurs visages\r\ndissimulés par des foulards.");
                R(ref s, "The next thing I knew, <E003 6>there was silence all around.", "L'instant d'après, <E003 6>le silence régnait tout autour.");
                R(ref s, "Genshin lay on the cobbled street.", "Genshin gisait sur les pavés.");
                R(ref s, "Blood was seeping from his left hand.<E003 15>\r\nHe'd shielded me.", "Le sang s'écoulait de sa main gauche.<E003 15>\r\nIl m'avait servi de bouclier.");
                return s;
            };

            // [22] BB\script\output\_sce04_c400_0040_eng#3
            entryTranslators[@"BB\script\output\_sce04_c400_0040_eng#3"] = (s) => {
                R(ref s, "It was on the ring finger of his <E006>left hand<E005> that he used to\r\nwear that ring.", "C'était à l'annulaire de sa <E006>main gauche<E005> qu'il avait coutume\r\nde porter cette bague.");
                R(ref s, "Ah!<E049><E003 16> <E025 3>Are, <E049><E003 10><E025 3><E341>are you saying...?", "Ah !<E049><E003 16> <E025 3>Êtes... <E049><E003 10><E025 3><E341>êtes-vous en train de dire... ?");
                R(ref s, "I've always believed those thugs were after me.", "J'ai toujours cru que ces brutes en avaient après moi.");
                R(ref s, "But now <E049><E003 12><E239><E025 2>I'm starting to question if perhaps I wasn't the\r\nintended target after all...", "Mais à présent, <E049><E003 12><E239><E025 2>je commence à me demander si je n'étais pas\r\nla cible visée, après tout...");
                R(ref s, "Wait, <E049><E003 10>but...", "Attendez, <E049><E003 10>mais...");
                R(ref s, "Genshin was arrested two days after that attack.", "Genshin a été arrêté deux jours après cette agression.");
                R(ref s, "And in that short interval, <E049><E003 6><E145 18 9><E003 10>the decisive evidence needed\r\nto indict him was miraculously found.", "Et dans ce court intervalle, <E049><E003 6><E145 18 9><E003 10>la preuve décisive requise\r\npour l'inculper fut miraculeusement découverte.");
                R(ref s, "You mean...<E049><E003 10><E164 1 71 1 2 5 0 1 1><E139 1><E025 1><E092 1>the ring was stolen from him?!<E049><E003 14>\r\n<E025 1>You think that's what those thugs were after that night?", "Vous voulez dire...<E049><E003 10><E164 1 71 1 2 5 0 1 1><E139 1><E025 1><E092 1>qu'on lui a volé la bague ?!<E049><E003 14>\r\n<E025 1>Vous pensez que c'est ce que cherchaient ces malfrats ce soir-là ?");
                R(ref s, "You...<E003 12> You pathetic coward...", "Vous...<E003 12> Espèce de lâche pathétique...");
                R(ref s, "You expect me to believe that you weren't involved?", "Vous croyez sérieusement me faire gober que vous n'étiez pas impliqué ?");
                R(ref s, "What do you mean by that?", "Qu'insinuez-vous par là ?");
                R(ref s, "It was you, <E049><E003 8>wasn't it?<E049><E003 12> <E025 2>You're the one who took it.<E049><E003 18>\r\n<E025 1><E338><E341>You stole my father's ring!", "C'était vous, <E049><E003 8>n'est-ce pas ?<E049><E003 12> <E025 2>C'est vous qui l'avez prise.<E049><E003 18>\r\n<E025 1><E338><E341>C'est vous qui avez volé la bague de mon père !");
                R(ref s, "You set the whole thing up so you could paint him as a\r\nmass murderer <E049><E003 8><E025 2><E338><E342>and have him arrest–", "Vous avez tout manigancé pour le faire passer pour un\r\ntueur de masse <E049><E003 8><E025 2><E338><E342>et le faire arrêt–");
                R(ref s, "Kazuma...<E023>\r\n--- PAGE 15 ---\r\n<E800 560><E563><E800 562><E145 1 7><E800 563><E118 1 0.7><E800 564><E003 20><E800 566><E041 1 0><E330><E025 3>...open your eyes.", "Kazuma...<E023>\r\n--- PAGE 15 ---\r\n<E800 560><E563><E800 562><E145 1 7><E800 563><E118 1 0.7><E800 564><E003 20><E800 566><E041 1 0><E330><E025 3>...ouvre les yeux.");
                R(ref s, "The truth can be completely obscured even when your\r\njudgement is only slightly clouded.", "La vérité peut être complètement obscurcie même quand le\r\njugement n'est que légèrement altéré.");
                R(ref s, "But at the moment...<E049><E003 13><E145 1 21><E003 15><E330><E025 2>you seem to be floundering through a\r\ndense fog.", "Mais en ce moment...<E049><E003 13><E145 1 21><E003 15><E330><E025 2>tu sembles patauger dans un épais\r\nbrouillard.");
                R(ref s, "Is that why you were so insistent I should be present in\r\nthis trial?<E049><E003 10> <E145 1 0><E003 15><E330><E025 3>To see you like this?", "Est-ce pour cela que tu insistais tant pour que je sois présent à\r\nce procès ?<E049><E003 10> <E145 1 0><E003 15><E330><E025 3>Pour te voir dans un tel état ?");
                R(ref s, "Well, <E049><E003 8>this is an amusing spectacle.", "Eh bien, <E049><E003 8>voilà un spectacle bien réjouissant.");
                R(ref s, "What a grandiose expression on your face!<E049><E003 15>\r\n<E025 2>As if you were Lady Justice herself.", "Quelle expression grandiloquente sur votre visage !<E049><E003 15>\r\n<E025 2>Comme si vous étiez la Justice incarnée.");
                R(ref s, "It seems you've thoroughly convinced yourself of this\r\nalleged fabrication of the autopsy results.", "Il semble que vous vous soyez fermement convaincu de cette\r\nprétendue falsification des résultats de l'autopsie.");
                R(ref s, "So much so that you're apparently blind to the blatant\r\n<E006>contradiction<E005> that would be born out of it.", "À tel point que vous êtes aveugle à la flagrante\r\n<E006>contradiction<E005> qui en découlerait.");
                R(ref s, "Though it's extremely hard to believe, <E049><E003 8>let us imagine that\r\nthere was some misconduct during the autopsy.", "Bien que ce soit difficilement concevable, <E049><E003 8>imaginons qu'il\r\ny ait eu faute lourde durant cette autopsie.");
                R(ref s, "If that were the case...<E003 14><E239>why would Asogi not have disputed\r\nthe findings in his trial?", "Si tel était le cas...<E003 14><E239>pourquoi Asogi n'a-t-il pas contesté\r\nces conclusions lors de son procès ?");
                R(ref s, "In the closed court hearing ten years ago, <E049><E003 10><E025 3>the defendant\r\nnever once denied the claims against him.", "Lors de l'audience à huis clos d'il y a dix ans, <E049><E003 10><E025 3>l'accusé\r\nn'a pas nié une seule fois les charges pesant sur lui.");
                R(ref s, "...Isn't that right, <E049><E003 8><E025 3>Lord van Zieks?", "...N'est-ce pas exact, <E049><E003 8><E025 3>Lord Van Peers ?");
                R(ref s, "Yes, <E049><E003 8>that is indeed correct.", "Oui, <E049><E003 8>c'est tout à fait exact.");
                R(ref s, "Upon hearing the verdict of ‘guilty’, <E049><E003 10><E025 3>he merely closed his\r\neyes, <E049><E003 8>quietly accepting the judgement.", "En entendant le verdict de « culpabilité », <E049><E003 10><E025 3>il a simplement fermé\r\nles yeux, <E049><E003 8>acceptant silencieusement le jugement.");
                R(ref s, "The actions of a man who has accepted responsibility for\r\nhis deeds <E049><E003 8><E025 3>and is resigned to his fate.", "L'attitude d'un homme qui assume la responsabilité de ses\r\nactes <E049><E003 8><E025 3>et se résigne à son sort.");
                return s;
            };

            // [23] BB\script\output\_sce04_c400_0040_eng#4
            entryTranslators[@"BB\script\output\_sce04_c400_0040_eng#4"] = (s) => {
                R(ref s, "But, <E049><E003 12>but then...", "Mais... <E049><E003 12>mais alors...");
                R(ref s, "Oh my...<E003 12>\r\n<E025 3>That is very strange.", "Bonté divine...<E003 12>\r\n<E025 3>C'est très étrange.");
                R(ref s, "If Mr Asogi did nothing to oppose the charges against him,\r\nthen...", "Si M. Asogi n'a rien fait pour contester les accusations portées contre lui,\r\nalors...");
                R(ref s, "...that would surely mean <E049><E003 10><E025 1><E338><E341>there was <E006>no fabricated\r\nevidence<E005>!", "...cela voudrait sûrement dire qu'il n'y a <E049><E003 10><E025 1><E338><E341><E006>pas eu de preuve\r\nfabriquée<E005> !");
                R(ref s, "An obvious conclusion at which you should have arrived\r\nmany minutes ago...<E049><E003 12><E025 3>Prosecutor Asogi.", "Une conclusion évidente à laquelle vous auriez dû parvenir\r\nil y a de longues minutes déjà...<E049><E003 12><E025 3>procureur Asogi.");
                R(ref s, "Your twisted loyalty and clouded judgement are\r\nhampering your ability for logical thought.", "Votre loyauté mal placée et votre jugement altéré entravent\r\nvotre capacité de raisonnement logique.");
                R(ref s, "Genshin Asogi's silence at his hearing can mean only one\r\nthing:", "Le silence de Genshin Asogi lors de son procès ne peut signifier qu'une\r\nseule chose :");
                R(ref s, "There was no fabrication of evidence <E049><E003 12><E025 1><E332>during the autopsy\r\nof his final victim ten years ago!", "Il n'y a eu aucune fabrication de preuve <E049><E003 12><E025 1><E332>durant l'autopsie\r\nde son ultime victime il y a dix ans !");
                R(ref s, "(But if that autopsy was all above board...)", "(Mais si cette autopsie s'est déroulée dans les règles de l'art...)");
                R(ref s, "(...there'll be nothing to stop Lord Stronghart bringing this\r\ntrial to an immediate conclusion!)", "(...rien n'empêchera Lord Stronghart de mettre fin immédiatement\r\nà ce procès !)");
                R(ref s, "Thank you, <E049><E003 6>Ryunosuke.<E049><E003 15>\r\n<E025 2>If it wasn't for your frank words just now...", "Merci, <E049><E003 6>Ryunosuke.<E049><E003 15>\r\n<E025 2>Sans tes paroles franches à l'instant...");
                R(ref s, "...this trial may very well have ended prematurely.", "...ce procès se serait fort bien terminé prématurément.");
                R(ref s, "What's this latest absurdity, <E049><E003 8><E025 3>Counsel?", "Quelle est cette nouvelle absurdité, <E049><E003 8><E025 3>Maître ?");
                R(ref s, "...your reasoning is perfectly sound...<E049><E003 15><E164 112 10 1 2 5 0 2 1><E139 112><E025 1>but for one, giant\r\nhole!", "...votre raisonnement est parfaitement logique...<E049><E003 15><E164 112 10 1 2 5 0 2 1><E139 112><E025 1>à une monumentale\r\nbrèche près !");
                R(ref s, "You claim my father's silence was due to the fact that\r\nthere was <E006>no fabricated evidence<E005>.", "Vous affirmez que le silence de mon père était dû au fait\r\nqu'il n'y avait <E006>pas de preuve fabriquée<E005>.");
                R(ref s, "But there's another possible explanation.", "Mais il existe une autre explication possible.");
                R(ref s, "You've overlooked the possibility <E049><E003 6><E164 112 10 1 2 8 0 2 1><E139 112><E025 1>that he had <E006>a reason<E005> for\r\nmaintaining that silence!", "Vous avez négligé l'éventualité <E049><E003 6><E164 112 10 1 2 8 0 2 1><E139 112><E025 1>qu'il ait eu <E006>une raison<E005> de\r\ngarder ce silence !");
                R(ref s, "Silence that would lead to him being convicted and sent to\r\nhis death?", "Un silence qui l'enverrait vers une condamnation et vers la mort ?");
                R(ref s, "If the autopsy results were an invention, <E049><E003 8><E164 18 65 1 2 5 0 2 1><E139 18><E025 1>there's no\r\nconceivable reason why the man wouldn't have protested!", "Si les résultats de l'autopsie avaient été inventés, <E049><E003 8><E164 18 65 1 2 5 0 2 1><E139 18><E025 1>il n'y a aucune\r\nraison concevable pour que cet homme n'ait pas protesté !");
                R(ref s, "Oh, <E049><E003 8><E025 2>those results <E006>were an invention<E005> alright.<E049><E003 10>\r\n<E025 3>There's no question of that.", "Oh, <E049><E003 8><E025 2>ces résultats <E006>étaient une invention<E005>, assurément.<E049><E003 10>\r\n<E025 3>Il n'y a aucun doute là-dessus.");
                R(ref s, "Or are you forgetting <E049><E003 8><E164 112 7 1 2 8 0 1 1><E139 112><E025 1>that two people with a connection to\r\nthat autopsy have been assassinated?", "Ou bien oubliez-vous <E049><E003 8><E164 112 7 1 2 8 0 1 1><E139 112><E025 1>que deux personnes liées à cette\r\nautopsie ont été assassinées ?");
                R(ref s, "If I force the grievances I feel from my mind...<E003 12><E025 3>I start to\r\nsee you in <E006>a very different light<E005>.", "Si je chasse de mon esprit mes griefs personnels...<E003 12><E025 3>je commence\r\nà vous voir sous <E006>un jour bien différent<E005>.");
                R(ref s, "I think perhaps it's you <E049><E003 15><E149 112 0 4><E145 112 0><E118 112 1.6><E003 6><E025 2><E238>who's been living in delusion\r\nthese ten years.", "Je pense que c'est peut-être vous <E049><E003 15><E149 112 0 4><E145 112 0><E118 112 1.6><E003 6><E025 2><E238>qui vivez dans l'illusion\r\ndepuis ces dix années.");
                R(ref s, "Kazuma-sama has created <E145 9 13><E338><E341>one last chance for us here,<E049><E003 6>\r\nMr Naruhodo.", "Maître Kazuma vient d'ouvrir <E145 9 13><E338><E341>une ultime chance pour nous ici,<E049><E003 6>\r\nmonsieur Naruhodo.");
                R(ref s, "If we can only show there was a reason for his father's\r\nsilence in his trial...", "Si nous parvenons à démontrer qu'il y avait une raison au silence\r\nde son père durant son procès...");
                R(ref s, "(A reason why the man would have said nothing even\r\nthough he was innocent...)", "(Une raison pour laquelle cet homme n'aurait rien dit bien\r\nqu'étant innocent...)");
                R(ref s, "(Could it have been part of some negotiation, perhaps?)", "(Cela faisait-il partie d'un quelconque accord, peut-être ?)");
                return s;
            };

            // [24] BB\script\output\_sce04_c400_0060_eng#2
            entryTranslators[@"BB\script\output\_sce04_c400_0060_eng#2"] = (s) => {
                R(ref s, "Enough rhetoric!<E049><E003 12>\r\n<E025 2>The court must be shown evidence.", "Assez de rhétorique !<E049><E003 12>\r\n<E025 2>Le tribunal exige des preuves.");
