            entryTranslators[@"BB\script\output\_sce04_c400_0060_eng#3"] = (s) => {
                R(ref s, "What proof do you have <E049><E003 8><E025 1><E346>that could possibly explain\r\nAsogi's silence in court?", "Quelle preuve avez-vous <E049><E003 8><E025 1><E346>qui pourrait éventuellement expliquer\r\nle silence d'Asogi au tribunal ?");
