            // [26] BB\script\output\_sce04_c400_0060_eng#4
            entryTranslators[@"BB\script\output\_sce04_c400_0060_eng#4"] = (s) => {
                R(ref s, "This <E049><E003 10><E025 1><E346>is the defence's answer to that question!", "Voici <E049><E003 10><E025 1><E346>la réponse de la défense à cette question !");
                R(ref s, "As I indicated before, <E049><E003 10><E239>my patience for rhetoric is growing\r\nthin.", "Comme je l'ai déjà souligné, <E049><E003 10><E239>ma patience à l'égard de la rhétorique\r\ns'amenuise.");
                R(ref s, "(You could've at least accompanied that penalty with an\r\nexplanation of why that answer was wrong...)", "(Vous auriez au moins pu assortir cette pénalité d'une explication\r\nsur la raison pour laquelle cette réponse est fausse...)");
                R(ref s, "If Kazuma-sama's father knew that the evidence being\r\nused to convict him was fabricated...", "Si le père de maître Kazuma savait que les preuves utilisées\r\npour le condamner étaient fabriquées...");
                R(ref s, "...why would he have said nothing in his trial?", "...pourquoi n'aurait-il rien dit lors de son procès ?");
                R(ref s, "If it were me, <E003 10><E333>I'd have protested my innocence until I was\r\nblue in the face.", "Si c'était moi, <E003 10><E333>j'aurais clamé mon innocence à m'en époumoner.");
                R(ref s, "So if we're right about the autopsy results, <E049><E003 8><E025 2>there must\r\nhave been a strong reason for his silence.", "Alors si nous avons raison sur les résultats de l'autopsie, <E049><E003 8><E025 2>il devait y avoir\r\nune puissante raison à son silence.");
                R(ref s, "Well then...<E003 12><E025 3>perhaps...", "Eh bien...<E003 12><E025 3>peut-être...");
                R(ref s, "...he was saying nothing <E003 8><E025 3><E330><E145 9 2>in exchange for some sort of\r\nclemency?", "...gardait-il le silence <E003 8><E025 3><E330><E145 9 2>en échange d'une forme\r\nde clémence ?");
                R(ref s, "(That could be it!)", "(Ça pourrait bien être ça !)");
                R(ref s, "My Lord!<E049><E003 12>\r\n<E025 3>The defence would like to–", "Votre Honneur !<E049><E003 12>\r\n<E025 3>La défense aimerait...");
                return s;
            };

            // [27] BB\script\output\_sce04_c400_0060_eng#5
            entryTranslators[@"BB\script\output\_sce04_c400_0060_eng#5"] = (s) => {
                R(ref s, "It's true that Genshin Asogi's silence during his trial\r\nresulted in his conviction...", "Il est vrai que le silence de Genshin Asogi durant son procès\r\na entraîné sa condamnation...");
                R(ref s, "...but that didn't actually lead to his execution.<E049><E003 12>\r\n<E025 3>On the contrary...", "...mais cela n'a pas conduit à son exécution.<E049><E003 12>\r\n<E025 3>Bien au contraire...");
                R(ref s, "...it led to his escape.<E049><E003 12> <E025 2>An escape that was only possible\r\nbecause he'd been sentenced to death.", "...cela a conduit à son évasion.<E049><E003 12> <E025 2>Une évasion qui ne fut possible\r\nque parce qu'il avait été condamné à mort.");
                R(ref s, "Although I find it hard to believe my father would have\r\nnegotiated in that way...<E003 12><E025 3>the defence is correct.", "Bien qu'il me soit pénible de croire que mon père ait négocié\r\nde la sorte...<E003 12><E025 3>la défense a vu juste.");
                R(ref s, "A fake execution, <E049><E003 8>falsification of a death certificate<E049><E003 10> and a\r\njailbreak inside a coffin...", "Une fausse exécution, <E049><E003 8>la falsification d'un certificat de décès<E049><E003 10> et une\r\névasion à l'intérieur d'un cercueil...");
                R(ref s, "Clearly such an elaborate plan <E145 112 0>couldn't have been\r\ncarried out by my father alone.", "Manifestement, un plan aussi élaboré <E145 112 0>n'aurait jamais pu être\r\nexécuté par mon père à lui seul.");
                R(ref s, "He must have had the help of <E006>a collaborator<E005> from the\r\njudiciary.", "Il a dû bénéficier de l'aide d'<E006>un complice<E005> au sein même\r\nde la magistrature.");
                R(ref s, "I have here the dismissal notice of the chief warder who\r\nwas working in the prison at the time.", "J'ai ici la lettre de renvoi du gardien-chef qui\r\nétait en poste à la prison à l'époque.");
                R(ref s, "The notes read:<E049><E003 12> <E025 3><E330>‘There are indications that the jailbreak\r\nwas in planning prior to the inmate's incarceration.’", "Les notes indiquent :<E049><E003 12> <E025 3><E330>« Des indices donnent à penser que cette évasion\r\nétait planifiée avant même l'incarcération du détenu. »");
                R(ref s, "...there were suggestions of some sort of negotiation<E049><E003 10>\r\n<E025 1><E346>between Mr Asogi and the British government!", "...il y a eu l'ébauche d'une forme de négociation<E049><E003 10>\r\n<E025 1><E346>entre M. Asogi et le gouvernement britannique !");
                R(ref s, "In exchange for his silence in court, <E049><E003 6>he was given an\r\nassurance that he would be broken out of prison...", "En échange de son silence au tribunal, <E049><E003 6>on lui a garanti\r\nqu'on le ferait évader de prison...");
                R(ref s, "Yes, <E049><E003 10>with that sort of clandestine agreement in place,<E049><E003 8> <E025 3>I can\r\nimagine he would have kept very quiet.", "Oui, <E049><E003 10>avec un tel accord clandestin conclu,<E049><E003 8> <E025 3>je conçois fort\r\nbien qu'il soit resté parfaitement silencieux.");
                R(ref s, "I would go further than that, in fact.<E049><E003 12>\r\n<E025 3>I would say...", "J'irais même encore plus loin que cela.<E049><E003 12>\r\n<E025 3>Je dirais...");
                R(ref s, "...that the elaborate jailbreak of Mr Asogi can be explained\r\nin no other way!", "...que l'évasion élaborée de M. Asogi ne peut s'expliquer\r\nd'aucune autre façon !");
                R(ref s, "Order!<E003 6> Order!<E049><E003 10>\r\n<E025 2><E145 61 5><E118 61 0.65><E003 10>First fabricated evidence <E049><E003 10>and now a jailbreak conspiracy?", "Silence !<E003 6> Silence !<E049><E003 10>\r\n<E025 2><E145 61 5><E118 61 0.65><E003 10>D'abord des preuves fabriquées <E049><E003 10>et maintenant une conspiration d'évasion ?");
                R(ref s, "Of course.<E049><E003 12> <E145 1 21><E025 2><E330>Because it's all intimately <E006>linked<E005>.", "Bien entendu.<E049><E003 12> <E145 1 21><E025 2><E330>Car tout cela est intimement <E006>lié<E005>.");
                R(ref s, "The prosecution wishes to summon new witnesses to the\r\nstand!", "L'accusation demande la convocation de nouveaux témoins à\r\nla barre !");
                R(ref s, "Witnesses?", "Des témoins ?");
                R(ref s, "People who can testify about the jailbreak that took place\r\nten years ago.", "Des personnes capables de témoigner sur l'évasion qui a eu lieu\r\nil y a dix ans.");
                R(ref s, "Governor Caidin...?<E049><E003 12><E145 9 92><E117 9 10><E003 5>\r\n<E346><E025 1>And the poor chief warder of the prison!", "Le directeur Caidin... ?<E049><E003 12><E145 9 92><E117 9 10><E003 5>\r\n<E346><E025 1>Et le pauvre gardien-chef de la prison !");
                R(ref s, "I won't allow this trial to turn into a farce!<E049><E003 12> <E025 2><E341>To summon\r\nthe governor of the prison after all these years...", "Je ne tolérerai point que ce procès tourne à la farce !<E049><E003 12> <E025 2><E341>Convoquer\r\nle directeur de la prison après toutes ces années...");
                R(ref s, "Oh, <E049><E003 8><E025 2>it wouldn't be any trouble, <E003 4>My Lord.", "Oh, <E049><E003 8><E025 2>cela ne posera aucune difficulté, <E003 4>Votre Honneur.");
                R(ref s, "My dear friend may appear a little rattlepated at times,<E049><E003 8>\r\n<E025 2>but I can assure you <E049><E003 10><E025 3>he is extremely thorough.", "Mon cher ami peut paraître un brin étourdi par moments,<E049><E003 8>\r\n<E025 2>mais je peux vous assurer <E049><E003 10><E025 3>qu'il est d'une rigueur absolue.");
                R(ref s, "He wired both Barclay and the local prison earlier...", "Il a télégraphié plus tôt à Barclay ainsi qu'à la prison locale...");
                R(ref s, "...asking Governor Caidin and Mr Vigil to attend the Old\r\nBailey as a matter of extreme urgency.", "...demandant au directeur Caidin et à M. Vigil de se rendre\r\nà Old Bailey d'extrême urgence.");
                R(ref s, "Mr Sholmes <E049><E003 8><E145 1 0><E118 1 0.6><E003 8><E025 2><E338><E341>did that?", "M. Sholmes <E049><E003 8><E145 1 0><E118 1 0.6><E003 8><E025 2><E338><E341>a fait cela ?");
                R(ref s, "Are, <E049><E003 10><E145 61 5><E118 61 0.7><E025 2><E341>are you telling me that...?", "Êtes... <E049><E003 10><E145 61 5><E118 61 0.7><E025 2><E341>êtes-vous en train de me dire que... ?");
                R(ref s, "Both men are, <E049><E003 8><E025 3>unless I'm much mistaken...", "Les deux hommes sont, <E049><E003 8><E025 3>si je ne m'abuse...");
                R(ref s, "...waiting just outside the courtroom at this very moment.", "...en train de patienter juste devant la salle d'audience en ce moment même.");
                R(ref s, "My Lord, <E049><E003 8><E025 2>you must permit this trial to proceed as you\r\ndeclared at its outset.", "Votre Honneur, <E049><E003 8><E025 2>vous devez autoriser ce procès à se poursuivre comme\r\nvous l'aviez déclaré à son ouverture.");
                R(ref s, "You promised that we would stop at nothing <E049><E003 3><E164 112 10 1 2 8 0 1 1><E139 112><E025 1>to uncover\r\nthe whole truth behind these disturbing findings!", "Vous avez promis que nous ne reculerions devant rien <E049><E003 3><E164 112 10 1 2 8 0 1 1><E139 112><E025 1>pour faire éclater\r\ntoute la vérité derrière ces troublantes constatations !");
                R(ref s, "Bring in the witnesses!", "Faites entrer les témoins !");
                R(ref s, "Make no mistake:<E049><E003 15> <E025 3>I, too, <E049><E003 12><E025 1><E046>would like nothing more than to\r\nlay this business to rest once and for all!", "Ne vous y trompez pas :<E049><E003 15> <E025 3>moi non plus, <E049><E003 12><E025 1><E046>je ne demande\r\nrien de plus que de régler cette affaire une bonne fois pour toutes !");
                return s;
            };

            // [28] BB\script\output\_sce04_c400_0060_eng#6
            entryTranslators[@"BB\script\output\_sce04_c400_0060_eng#6"] = (s) => {
                R(ref s, "We've wasted enough time!", "Nous avons perdu assez de temps !");
                R(ref s, "It's clear to me <E049><E003 8><E025 2>that any further discussion of this case will\r\nbe fruitless.", "Il m'apparaît clairement <E049><E003 8><E025 2>que toute nouvelle discussion sur cette affaire sera\r\nstérile.");
                R(ref s, "Barok van Zieks, <E049><E003 8><E025 2>I would like to think that however\r\nmisguided...", "Drake Van Peers, <E049><E003 8><E025 2>j'aimerais croire que, si fourvoyé fussiez-vous...");
                R(ref s, "...you acted out of a sense of justice nonetheless.<E049><E003 12>\r\n<E025 3>Though it pains me to have reached this conclusion...", "...vous avez néanmoins agi par sens de la justice.<E049><E003 12>\r\n<E025 3>Bien qu'il me soit douloureux d'en arriver à cette conclusion...");
                R(ref s, "No!<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Wait, My Lord!", "Non !<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Attendez, Votre Honneur !");
                R(ref s, "In accordance with the findings of this court, <E049><E003 6><E025 3>I hereby\r\npronounce the defendant, <E049><E003 6><E025 3>Barok van Zieks...", "Conformément aux conclusions de ce tribunal, <E049><E003 6><E025 3>je déclare\r\nici l'accusé, <E049><E003 6><E025 3>Drake Van Peers...");
                R(ref s, "That concludes business.<E049><E003 10>\r\n<E025 2>Court is adjourned!", "Ceci clôt les débats.<E049><E003 10>\r\n<E025 2>L'audience est levée !");
                return s;
            };

            // [29] BB\script\output\_sce04_c401_0000_eng#2
            entryTranslators[@"BB\script\output\_sce04_c401_0000_eng#2"] = (s) => {
                R(ref s, "Would the new witnesses state their names and\r\noccupations for the court, <E003 4>please.", "Que les nouveaux témoins déclinent leurs nom et profession\r\nau tribunal, <E003 4>s'il vous plaît.");
                R(ref s, "Aye.<E049><E003 12> <E025 2>Barry Caidin, <E049><E003 8>governor of Barclay Prison.", "Affirmatif.<E049><E003 12> <E025 2>Barry Caidin, <E049><E003 8>directeur de la prison de Barclay.");
                R(ref s, "Everyone calls me Gossip.<E049><E003 12>\r\n<E025 2>I sell jaunty little titbits to passers-by, <E049><E003 8><E025 3>you–", "Tout le monde m'appelle Gossip.<E049><E003 12>\r\n<E025 2>Je vends de joyeux petits ragots aux passants, <E049><E003 8><E025 3>vous...");
                R(ref s, "Um, <E003 13><E169 1 3><E025 3>your other persona, <E049><E003 8>if you don't mind...", "Hum, <E003 13><E169 1 3><E025 3>votre autre personnalité, <E049><E003 8>si cela ne vous dérange pas...");
                R(ref s, "Oh, <E049><E003 8>I do beg your pardon.<E049><E003 12>\r\n<E025 3>Of course...", "Oh, <E049><E003 8>veuillez m'excuser.<E049><E003 12>\r\n<E025 3>Bien entendu...");
                R(ref s, "My name is Daley Vigil.<E049><E003 12> <E025 2>I used to be the chief warder at\r\nBarclay Prison.", "Je m'appelle Daley Vigil.<E049><E003 12> <E025 2>J'étais autrefois gardien-chef à la\r\nprison de Barclay.");
                R(ref s, "The reason you've been summoned here to court today...", "La raison de votre convocation au tribunal aujourd'hui...");
                R(ref s, "...is to testify about the jailbreak <E049><E003 10>of the so-called\r\n‘Professor’ ten years ago.", "...est de témoigner au sujet de l'évasion <E049><E003 10>dudit « Professeur »\r\nil y a dix ans.");
                R(ref s, "Losh!<E049><E003 16> The Professor?!<E049><E003 14> <E335><E342><E025 1>We've already been through all\r\nthis afore.<E049><E003 12> A decade ago!", "Diantre !<E049><E003 16> Le Professeur ?!<E049><E003 14> <E335><E342><E025 1>On a déjà épluché tout ça\r\nautrefois !<E049><E003 12> Il y a dix ans !");
                R(ref s, "And the conclusion <E049><E003 10><E145 127 74><E118 127 0.6><E003 11><E025 2><E333>was that there was'nae anythin'\r\nuntoward happened.", "Et la conclusion, <E049><E003 10><E145 127 74><E118 127 0.6><E003 11><E025 2><E333>c'était qu'il s'était rien passé d'anormal du tout.");
                R(ref s, "A convict escaped from your prison, <E049><E003 6>Governor.<E049><E003 10><E145 1 7><E144 1>\r\n<E025 1><E346>Hardly what you'd call ‘nothing untoward’!", "Un détenu s'est évadé de votre prison, <E049><E003 6>Monsieur le Directeur.<E049><E003 10><E145 1 7><E144 1>\r\n<E025 1><E346>C'est difficilement ce qu'on peut appeler « rien d'anormal » !");
                R(ref s, "The convict's death certificate was somehow falsified\r\nafter he was allegedly executed...", "Le certificat de décès du prisonnier a été falsifié d'une manière ou d'une autre\r\naprès qu'il a prétendument été exécuté...");
                R(ref s, "...and he escaped the prison inside his own coffin.<E049><E003 10><E145 1 0><E118 1 1.0><E003 6>\r\n<E025 3>A plan of that complexity...", "...et il s'est échappé de la prison à l'intérieur de son propre cercueil.<E049><E003 10><E145 1 0><E118 1 1.0><E003 6>\r\n<E025 3>Un plan d'une telle complexité...");
                R(ref s, "...could never have been carried out without the help of\r\nsomebody of influence inside the prison.", "...n'aurait jamais pu être exécuté sans l'aide d'une\r\npersonne d'influence au sein même de l'établissement.");
                R(ref s, "Governor Caidin, <E049><E003 10>don't imagine that the passage of time\r\nwill afford you any protection.", "Directeur Caidin, <E049><E003 10>n'allez pas croire que le temps écoulé\r\nvous offrira la moindre protection.");
                R(ref s, "If it turns out that you were involved in the plot to break\r\nMr Asogi out of your prison, <E049><E003 10><E025 3>then of course...", "S'il s'avère que vous avez trempé dans le complot pour faire évader\r\nM. Asogi de votre prison, <E049><E003 10><E025 3>alors évidemment...");
                R(ref s, "...the consequences will be very serious.<E049><E003 15><E145 112 4><E118 112 0.9><E149 112 5 4><E003 10>\r\n<E025 3>In all likelihood, <E049><E003 8>a capital punishment.", "...les conséquences seront des plus graves.<E049><E003 15><E145 112 4><E118 112 0.9><E149 112 5 4><E003 10>\r\n<E025 3>Selon toute vraisemblance, <E049><E003 8>la peine capitale.");
                R(ref s, "Gads!<E049><E003 16> <E025 1>Hold on there, laddie!<E049><E003 14>\r\n<E025 2><E341>All I did was–", "Miséricorde !<E049><E003 16> <E025 1>Doucement là, p'tit gars !<E049><E003 14>\r\n<E025 2><E341>Tout ce que j'ai fait, c'est...");
                R(ref s, "Witness!<E049><E003 10> <E025 3>...Governor Caidin...", "Témoin !<E049><E003 10> <E025 3>...Directeur Caidin...");
                R(ref s, "Hm?<E049><E003 15> <E169 127 3><E025 1><E145 127 78><E346>Ah, <E049><E003 12>aye, SIR!", "Hein ?<E049><E003 15> <E169 127 3><E025 1><E145 127 78><E346>Ah, <E049><E003 12>OUIP, MONSIEUR !");
                R(ref s, "You have a critical role to play in the public safety of our\r\ncountry.<E049><E003 10><E025 3> A great responsibility to shoulder.", "Vous avez un rôle crucial à jouer dans la sécurité publique de notre\r\npays.<E049><E003 10><E025 3> Une lourde responsabilité repose sur vos épaules.");
                R(ref s, "The significance of your testimony in court cannot be\r\nunderstated.<E049><E003 10> <E025 3>Therefore...<E003 10>think carefully before you speak.", "L'importance de votre déposition devant ce tribunal ne saurait être\r\nsous-estimée.<E049><E003 10> <E025 3>Par conséquent...<E003 10>réfléchissez bien avant de parler.");
                R(ref s, "And Prosecutor Asogi...<E049><E003 10><E145 61 2><E003 8><E330><E025 2>if you threaten the witness again,<E049><E003 8>\r\nyou will be held in contempt of court.", "Et procureur Asogi...<E049><E003 10><E145 61 2><E003 8><E330><E025 2>si vous menacez encore le témoin,<E049><E003 8>\r\nvous serez accusé d'outrage à magistrat.");
                R(ref s, "My apologies, <E049><E003 8>My Lord.", "Mes excuses, <E049><E003 8>Votre Honneur.");
                R(ref s, "There's no disputing the fact <E049><E003 8><E025 3>that an intricate jailbreak\r\nplot was enacted ten years ago.", "Il est incontestable <E049><E003 8><E025 3>qu'un plan d'évasion sophistiqué\r\na été orchestré il y a dix ans.");
                R(ref s, "Clearly, <E049><E003 8>you were both involved in some way.", "Manifestement, <E049><E003 8>vous étiez tous deux impliqués d'une façon ou d'une autre.");
                R(ref s, "So you will testify before the court now and explain\r\nexactly what took place!", "Vous allez donc témoigner devant la cour à présent et expliquer\r\nexactement ce qui s'est déroulé !");
                R(ref s, "Very well.<E049><E003 10> <E025 2>Let the witnesses give their formal testimony.", "Fort bien.<E049><E003 10> <E025 2>Que les témoins fassent leur déposition formelle.");
                R(ref s, "Tell the court everything you know <E049><E003 10><E025 1><E341>of the plot to break\r\nAsogi out of Barclay ten years ago!", "Dites au tribunal tout ce que vous savez <E049><E003 10><E025 1><E341>sur le complot d'évasion\r\nd'Asogi de Barclay il y a dix ans !");
                return s;
            };

            // [30] BB\script\output\_sce04_c401_0010_eng#2
            entryTranslators[@"BB\script\output\_sce04_c401_0010_eng#2"] = (s) => {
                R(ref s, "– The Jailbreak Plot –", "– Le complot d'évasion –");
                R(ref s, "It was the day that Japanese jock was found guilty.<E049><E003 12>\r\nThe directive came from the Prosecutor's Office.", "C'était le jour où ce bougre de Japonais a été jugé coupable.<E049><E003 12>\r\nLa consigne venait tout droit du Parquet général.");
                R(ref s, "I assigned the convict to the chief warder Vigil here,<E049><E003 8> and\r\nput the plan into action behind the scenes.", "J'ai confié le détenu au gardien-chef Vigil ici présent,<E049><E003 8> et\r\nj'ai mis le plan à exécution en coulisses.");
                R(ref s, "I was responsible for Asogi right up until the night of his\r\nexecution.<E049><E003 10> <E025 3><E341>But I knew nothing of any plot...", "J'ai eu la charge d'Asogi jusqu'à la nuit même de son\r\nexécution.<E049><E003 10> <E025 3><E341>Mais j'ignorais tout d'un quelconque complot...");
                R(ref s, "I dinnae ken if there were some negotiations between the\r\nconvict and the Prosecutor's Office.", "J'en sais fichtre rien s'il y a eu des pourparlers entre le\r\ncondamné et le Parquet général.");
                R(ref s, "All I did was carry oot my duty!<E049><E003 15><E145 127 78>\r\n<E025 1><E346><E339>For Her Majesty's great British Empire!", "Tout ce que j'ai fait, c'est accomplir mon devoir !<E049><E003 15><E145 127 78>\r\n<E025 1><E346><E339>Pour le glorieux Empire britannique de Sa Majesté !");
                return s;
            };

            // [31] BB\script\output\_sce04_c401_0010_eng#3
            entryTranslators[@"BB\script\output\_sce04_c401_0010_eng#3"] = (s) => {
                R(ref s, "A directive from the Prosecutor's Office?<E049><E003 12><E145 1 7><E144 1>\r\n<E025 1><E332>Are you saying that was the jailbreak plot?!", "Une consigne du Parquet général ?<E049><E003 12><E145 1 7><E144 1>\r\n<E025 1><E332>Voulez-vous dire que c'était cela, le plan d'évasion ?!");
                R(ref s, "...Aye, <E049><E003 10>that's right.", "...Ouip, <E049><E003 10>c'est ça.");
                R(ref s, "Who sent it?!<E049><E003 8><E164 112 7 1 2 9 0 2 1><E139 112>\r\n<E025 1>Who authorised that plan?!", "Qui l'a envoyée ?!<E049><E003 8><E164 112 7 1 2 9 0 2 1><E139 112>\r\n<E025 1>Qui a autorisé un tel plan ?!");
                R(ref s, "I dinnae ken that.", "J'en sais point.");
                R(ref s, "You're saying you don't know?!", "Vous prétendez que vous ne savez pas ?!");
                R(ref s, "Listen, <E049><E003 8><E025 2>there was'nae a thing aboot that Professor case\r\nthat was'nae unusual in some way.", "Écoutez, <E049><E003 8><E025 2>y avait pas un seul détail dans cette affaire du Professeur\r\nqui sortait point de l'ordinaire.");
                R(ref s, "I did'nae ask any questions.<E049><E003 14> <E025 2><E333>I just did what I was told to\r\ndo.<E049><E003 10> <E025 2>More than that, <E049><E003 6>I could'nae tell ya.", "J'ai point posé d'questions.<E049><E003 14> <E025 2><E333>J'ai juste fait c'qu'on m'a dit d'\r\nfaire.<E049><E003 10> <E025 2>Plus que ça, <E049><E003 6>j'pourrais point vous en dire.");
                R(ref s, "But if the jailbreak plan originated from <E006>the Prosecutor's\r\nOffice<E005>...", "Mais si ce plan d'évasion provenait <E006>du Parquet\r\ngénéral<E005>...");
                R(ref s, "...then one thing is very clear:", "...alors une chose est limpide :");
                R(ref s, "As suspected, <E049><E003 10><E025 3>there were clandestine dealings going on\r\nbetween Mr Asogi and that office.", "Comme nous nous en doutions, <E049><E003 10><E025 3>des tractations secrètes ont eu lieu\r\nentre M. Asogi et cette institution.");
                R(ref s, "The jailbreak was promised <E049><E003 12><E025 1><E346><E006>in exchange<E005> for Mr Asogi\r\nadmitting to crimes he didn't commit!", "L'évasion lui avait été promise <E049><E003 12><E025 1><E346><E006>en échange<E005> d'aveux\r\npour des crimes que M. Asogi n'avait pas commis !");
                R(ref s, "That, <E049><E003 8>Counsel, <E049><E003 12><E025 2>is nothing more than speculation on your\r\npart.", "Ceci, <E049><E003 8>Maître, <E049><E003 12><E025 2>n'est rien de plus qu'une pure conjecture de votre\r\npart.");
                R(ref s, "So...<E003 12><E025 3>let me ask the defence...", "Alors...<E003 12><E025 3>laissez-moi demander à la défense...");
                R(ref s, "Oh!<E049><E003 14> Yes, My Lord?", "Oh !<E049><E003 14> Oui, Votre Honneur ?");
                R(ref s, "I fail to see how these witnesses have any more pertinent\r\ninformation here.", "Je ne vois guère quelles informations pertinentes supplémentaires\r\nces témoins pourraient apporter.");
                R(ref s, "Do you intend to assert your right to a cross-examination?", "Avez-vous l'intention de faire valoir votre droit au contre-interrogatoire ?");
                R(ref s, "Absolutely!<E049><E003 18> I have no intention of squandering a single\r\nopportunity, <E049><E003 6>My Lord!", "Absolument !<E049><E003 18> Je n'ai nulle intention de gaspiller la moindre\r\nopportunité, <E049><E003 6>Votre Honneur !");
                R(ref s, "...It seems all you Japanese are fiercely tenacious.", "...Il semble que vous autres Japonais soyez farouchement tenaces.");
                R(ref s, "Proceed, <E003 4>Counsel!", "Poursuivez, <E003 4>Maître !");
                return s;
            };

